import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const y=JSON.parse('{"title":"2018Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2018Q1 Ceph社区季度进展报告","date":"2018-03-01T00:00:00.000Z","updated":"2018-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018Q1_Ceph社区季度总结.md","filePath":"posts/2018/2018Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),h={name:"posts/2018/2018Q1_Ceph社区季度总结.md"};function l(_,e,n,i,p,s){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="ceph-社区-2018-q1-季度进展报告" tabindex="-1">Ceph 社区 2018 Q1 季度进展报告 <a class="header-anchor" href="#ceph-社区-2018-q1-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2018 Q1 季度进展报告&quot;">​</a></h1><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>2018年第一季度，Ceph 社区围绕以下几个核心方向持续深入讨论：</p><p><strong>BlueStore 性能与稳定性</strong> BlueStore 是本季度最高频的讨论主题。从异步读取支持、缓存策略重构，到与 RocksDB 的缓存协调，几乎每周的性能例会都有相关议题。详见 <a href="./2018-JAN-04_-_-Ceph_Performance_Weekly.html">2018-JAN-04 性能周会</a> 和 <a href="./2018-FEB-22_-_Ceph_Performance_Weekly.html">2018-FEB-22 性能周会</a>。</p><p><strong>OSD 性能优化与异步化改造</strong> OSD 的同步基础设施被多次指出存在冗余开销，社区持续推进对象存储接口（OST）的异步化改造，并讨论了执行上下文分析和调用图构建。详见 <a href="./2018-FEB-01_-_Ceph_Performance_Weekly.html">2018-FEB-01 性能周会</a>。</p><p><strong>RocksDB 缓存与元数据管理</strong> RocksDB 的 Bloom filter 内存占用、索引/过滤器缓存分配、以及 BlueStore 与 RocksDB 之间的缓存再平衡机制，在 3 月份的会议中成为焦点。详见 <a href="./2018-MAR-01_-_Ceph_Performance_Weekly.html">2018-MAR-01 性能周会</a>。</p><p><strong>Dashboard v2 与管理工具现代化</strong> 社区启动了基于 Angular 2 + CheryPy 的 Dashboard v2 开发，并在 Ceph Day Germany 上展示了 openATIC 等管理工具的进展。</p><p><strong>Kubernetes/容器化部署</strong> Rook 项目成为 Kubernetes 上部署 Ceph 的首选方案，并计划与 Ceph Mimic 版本同步发布。详见 <a href="/VideoSummary/posts/2018/2018-JAN-03_-_-_Ceph_Developer_Monthly.html">2018-JAN-03 开发者月会</a>)。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="bluestore-异步读取" tabindex="-1">BlueStore 异步读取 <a class="header-anchor" href="#bluestore-异步读取" aria-label="Permalink to &quot;BlueStore 异步读取&quot;">​</a></h3><p>社区提交了为 BlueStore 添加异步读取支持的大型 PR，但发现存在性能回归问题，需要在特定场景下回退到同步路径。该工作持续贯穿整个季度。详见 <a href="/VideoSummary/posts/2018/2018-JAN-04_-_-_Ceph_Performance_Weekly.html">2018-JAN-04 性能周会</a>)。</p><h3 id="crc-缓存补丁" tabindex="-1">CRC 缓存补丁 <a class="header-anchor" href="#crc-缓存补丁" aria-label="Permalink to &quot;CRC 缓存补丁&quot;">​</a></h3><p>一个简洁有效的 CRC 缓存补丁在 1 月完成并进入 QA 测试阶段，被认为是低风险高收益的优化。</p><h3 id="qat-quick-assist-technology-支持" tabindex="-1">QAT（Quick Assist Technology）支持 <a class="header-anchor" href="#qat-quick-assist-technology-支持" aria-label="Permalink to &quot;QAT（Quick Assist Technology）支持&quot;">​</a></h3><p>新增了对 Intel QAT 硬件加速的支持，涵盖压缩和加密加速，但集成过程中遇到若干问题需要解决。详见 <a href="./2018-JAN-11_-_Ceph_Performance_Weekly.html">2018-JAN-11 性能周会</a>。</p><h3 id="vp-网络集成探索" tabindex="-1">VP 网络集成探索 <a class="header-anchor" href="#vp-网络集成探索" aria-label="Permalink to &quot;VP 网络集成探索&quot;">​</a></h3><p>1 月的性能周会中，社区探讨了将 VPP（Virtual Packet Processing）集成到 Ceph 的可能性，讨论了通过 VPP 通信库在用户空间处理网络操作，以及作为 RGW 插件的方案。详见 <a href="./2018-JAN-18_-_Ceph_Performance_Weekly.html">2018-JAN-18 性能周会</a>。</p><h3 id="messenger-v2" tabindex="-1">Messenger v2 <a class="header-anchor" href="#messenger-v2" aria-label="Permalink to &quot;Messenger v2&quot;">​</a></h3><p>Messenger v2 的开发持续推进，重点在于身份验证和传输加密，计划集成 GSSAPI 以支持 Kerberos 等认证协议。详见 <a href="/VideoSummary/posts/2018/2018-FEB-07_-_-_Ceph_Developer_Monthly.html">2018-FEB-07 开发者月会</a>)。</p><h3 id="集群级别复制-multi-site-replication" tabindex="-1">集群级别复制（Multi-site Replication） <a class="header-anchor" href="#集群级别复制-multi-site-replication" aria-label="Permalink to &quot;集群级别复制（Multi-site Replication）&quot;">​</a></h3><p>2 月开发者月会讨论了集群级别复制的架构细节，引入了新模块处理复制工作，并设计了日志条目和操作缓存机制来管理复制操作。</p><h3 id="rgw-对象变更日志" tabindex="-1">RGW 对象变更日志 <a class="header-anchor" href="#rgw-对象变更日志" aria-label="Permalink to &quot;RGW 对象变更日志&quot;">​</a></h3><p>3 月开发者月会讨论了为 RGW 添加对象变更日志功能，以便备份系统等外部工具可以追踪对象变化，并考虑兼容 S3 日志接口。详见 <a href="./2018-MAR-07_-_Ceph_Developer_Monthly.html">2018-MAR-07 开发者月会</a>。</p><h3 id="bluestore-rocksdb-缓存自动调优" tabindex="-1">BlueStore/RocksDB 缓存自动调优 <a class="header-anchor" href="#bluestore-rocksdb-缓存自动调优" aria-label="Permalink to &quot;BlueStore/RocksDB 缓存自动调优&quot;">​</a></h3><p>3 月的性能周会中，社区开始研究在 BlueStore 和 RocksDB 之间动态调整缓存分配的机制，目标是根据实际工作负载自动优化缓存比例。详见 <a href="/VideoSummary/posts/2018/2018-Mar-15_-_-_Ceph_Performance_Weekly.html">2018-Mar-15 性能周会</a>)。</p><h3 id="seastar-spdk-新存储后端-c-store" tabindex="-1">Seastar/SPDK 新存储后端（C Store） <a class="header-anchor" href="#seastar-spdk-新存储后端-c-store" aria-label="Permalink to &quot;Seastar/SPDK 新存储后端（C Store）&quot;">​</a></h3><p>1 月开发者月会讨论了基于 Seastar 框架和 SPDK 库的新存储后端，提供日志结构化存储格式，专为高速 NVMe 设备设计，命名讨论中出现了&quot;C Store&quot;或&quot;C18 Store&quot;等候选名称。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p><strong>Ceph Luminous 回顾与 Mimic 规划</strong> Ceph Day Germany 上对 Luminous 版本进行了全面回顾，介绍了 BlueStore 正式成为默认后端、Ceph Manager 引入等重要变化。同时，Rook 项目计划与即将发布的 Mimic 版本同步。详见 <a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_Luminous_is_out_what_s_in_it_for_you.html">Ceph Day Germany - Ceph Luminous is out</a>)。</p><p><strong>BlueStore 缓存策略讨论</strong> 社区认真讨论了是否移除 BlueStore 自身的缓存层、仅依赖 RocksDB 缓存管理元数据的方案，但决定在收集更多 Bloom filter 内存占用数据后再做决定，暂时维持默认的 50/50 缓存分配策略。</p><p><strong>Specter 漏洞影响评估</strong> 1 月会议中，社区评估了 Spectre 漏洞对 Intel 处理器性能的潜在影响，Red Hat 性能团队介入研究解决方案。详见 <a href="./2018-JAN-18_-_Ceph_Performance_Weekly.html">2018-JAN-18 性能周会</a>。</p><p><strong>新配置管理系统（mod）</strong> 1 月开发者月会确认了新配置管理系统的方向，支持配置存储、解析、验证和展示，但身份验证功能尚未完成，列为后续工作项。</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><h3 id="ceph-day-germany" tabindex="-1">Ceph Day Germany <a class="header-anchor" href="#ceph-day-germany" aria-label="Permalink to &quot;Ceph Day Germany&quot;">​</a></h3><p>本季度举办了 Ceph Day Germany，涵盖多个主题演讲：</p><ul><li><strong>openATTIC 管理工具</strong>：展示了基于 openATTIC 的自动化部署和集群管理能力。详见 <a href="/VideoSummary/posts/2018/Ceph_Day_German_-_Ceph_Management_and_Monitoring_with_openATTIC.html">Ceph Day Germany - Management and Monitoring with openATTIC</a>)。</li><li><strong>CERN 大科学应用</strong>：CERN 分享了在两个数据中心运行 Ceph 集群（最大 5.5PB）的经验，涵盖物理实验数据、S3 存储和 HPC 场景。详见 <a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_for_Big_Science.html">Ceph Day Germany - Ceph for Big Science</a>)。</li><li><strong>SAP 企业云实践</strong>：SAP 分享了基于 Ceph 构建&quot;cattle cloud&quot;的实践，使用 Saltstack 进行自动化部署。详见 <a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_at_SAP_-_How_to_build_a_cattle_cloud.html">Ceph Day Germany - Ceph at SAP</a>)。</li><li><strong>Intel 平台与 SD 性能</strong>：讨论了 Ceph 在新型 Intel 平台和 SSD 上的性能表现。详见 <a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_Performance_on_New_Intel_Platforms_and_SSDs.html">Ceph Day Germany - Ceph Performance on New Intel Platforms and SSDs</a>)。</li><li><strong>SD-only 性能方案</strong>：探讨了全 SSD 存储介质下的 Ceph 性能优化策略。详见 <a href="./Ceph_Day_Germany_-_SD_only_Performance_with_Ceph.html">Ceph Day Germany - SD only Performance with Ceph</a>。</li><li><strong>Ceph mgr 与 Kubernetes集成</strong>：介绍了 CephCO 容器编排工具和 Rook 项目的进展。详见 <a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Development_update_Ceph_mgr_and_Kubernetes.html">Ceph Day Germany - Development update Ceph mgr and Kubernetes</a>)。</li><li><strong>croit 管理方案</strong>：一家基于 Rust 开发 Ceph 管理工具的初创公司分享了其产品。详见 <a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Everyone_can_Build_and_Maintain_a_Ceph_Cluster_with_croit.html">Ceph Day Germany - Everyone can Build and Maintain a Ceph Cluster with croit</a>)。</li></ul><h3 id="开发者月会" tabindex="-1">开发者月会 <a class="header-anchor" href="#开发者月会" aria-label="Permalink to &quot;开发者月会&quot;">​</a></h3><ul><li>1 月月会（<a href="/VideoSummary/posts/2018/2018-JAN-03_-_-_Ceph_Developer_Monthly.html">2018-JAN-03</a>)）：讨论了配置管理、Rook、Easy Clones、OSD 性能优化和新存储后端等多个方向。</li><li>2 月月会（<a href="/VideoSummary/posts/2018/2018-FEB-07_-_-_Ceph_Developer_Monthly.html">2018-FEB-07</a>)）：重点讨论 Dashboard v2、Messenger v2 和集群级别复制。</li><li>3 月月会（<a href="/VideoSummary/posts/2018/2018-MAR-07_-_-_Ceph_Developer_Monthly.html">2018-MAR-07</a>)）：讨论 RGW 对象变更日志、多区域同步模块改进和配置历史记录功能。</li></ul><h3 id="性能周会" tabindex="-1">性能周会 <a class="header-anchor" href="#性能周会" aria-label="Permalink to &quot;性能周会&quot;">​</a></h3><p>本季度共举办 9 次性能周会，参与者包括来自 Red Hat 等公司的核心开发者，持续跟踪性能相关 PR 的进展，形成了稳定的周期性协作机制。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度的讨论内容，预计 2018 Q2 将重点推进以下方向：</p><ol><li><p><strong>BlueStore 异步读取落地</strong>：解决性能回归问题后，异步读取 PR 有望合并，进一步提升 BlueStore 的 I/O 性能。</p></li><li><p><strong>BlueStore/RocksDB 缓存自动调优</strong>：缓存再平衡机制的代码开发将继续，目标是在 Mimic 版本中提供更智能的缓存管理。</p></li><li><p><strong>Dashboard v2 发布</strong>：Angular 2 前端开发接近完成，预计 Q2 可提交可审查版本，并逐步集成监控功能。</p></li><li><p><strong>Messenger v2 身份验证</strong>：Kerberos/GSSAPI 集成工作将继续推进，为集群通信提供加密和认证能力。</p></li><li><p><strong>Rook 与 Mimic 同步发布</strong>：Rook 项目将与 Ceph Mimic 版本协调发布节奏，推动 Kubernetes 上的 Ceph 部署标准化。</p></li><li><p><strong>Seastar/SPDK 新存储后端原型</strong>：C Store（基于 Seastar + SPDK）的早期原型开发将继续，为下一代高速存储设备做准备。</p></li><li><p><strong>RGW 对象变更日志</strong>：该功能将继续开发，为备份和数据同步场景提供基础能力。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2018/2018-FEB-01_-_-_Ceph_Performance_Weekly.html">2018-FEB-01 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-FEB-07_-_-_Ceph_Developer_Monthly.html">2018-FEB-07 -- Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-FEB-08_-_-_Ceph_Performance_Weekly.html">2018-FEB-08 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-FEB-15_-_-_Ceph_Performance_Weekly.html">2018-FEB-15 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-FEB-22_-_-_Ceph_Performance_Weekly.html">2018-FEB-22 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-JAN-03_-_-_Ceph_Developer_Monthly.html">2018-JAN-03 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-JAN-04_-_-_Ceph_Performance_Weekly.html">2018-JAN-04 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-JAN-11_-_-_Ceph_Performance_Weekly.html">2018-JAN-11 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-JAN-18_-_-_Ceph_Performance_Weekly.html">2018-JAN-18 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-MAR-01_-_-_Ceph_Performance_Weekly.html">2018-MAR-01 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-MAR-07_-_-_Ceph_Developer_Monthly.html">2018-MAR-07 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-MAR-08_-_-_Ceph_Performance_Weekly.html">2018-MAR-08 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/2018-Mar-15_-_-_Ceph_Performance_Weekly.html">2018-Mar-15 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_German_-_Ceph_Management_and_Monitoring_with_openATTIC.html">Ceph Day German - Ceph Management and Monitoring with openATTIC</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_German_-_Five_years_of_Ceph_and_Outlook.html">Ceph Day German - Five years of Ceph and Outlook</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_10_ways_to_break_your_Ceph_cluster.html">Ceph Day Germany - 10 ways to break your Ceph cluster</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_Luminous_is_out_what_s_in_it_for_you.html">Ceph Day Germany - Ceph Luminous is out what&#39;s in it for you</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_Performance_on_New_Intel_Platforms_and_SSDs.html">Ceph Day Germany - Ceph Performance on New Intel Platforms and SSDs</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_at_SAP_-_How_to_build_a_cattle_cloud.html">Ceph Day Germany - Ceph at SAP: How to build a cattle cloud</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Ceph_for_Big_Science.html">Ceph Day Germany - Ceph for Big Science</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Development_update_Ceph_mgr_and_Kubernetes.html">Ceph Day Germany - Development update Ceph mgr and Kubernetes</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_Everyone_can_Build_and_Maintain_a_Ceph_Cluster_with_croit.html">Ceph Day Germany - Everyone can Build and Maintain a Ceph Cluster with croit</a>)</li><li><a href="/VideoSummary/posts/2018/Ceph_Day_Germany_-_SSD_only_Performance_with_Ceph.html">Ceph Day Germany - SSD only Performance with Ceph</a>)</li></ul>',50)])])}const u=a(h,[["render",l]]);export{y as __pageData,u as default};
